create extension if not exists pgcrypto;
create table if not exists public.users(id uuid primary key default gen_random_uuid(),first_name text not null,last_name text not null,phone text unique not null,created_at timestamptz not null default now());
create table if not exists public.trips(id uuid primary key default gen_random_uuid(),name text not null,invite_code text unique not null,destination text,start_date date,end_date date,commit_deadline date not null,deposit_amount numeric(10,2) not null default 0,venmo_username text,cashtag text,cover_image text,is_demo boolean not null default false,created_by uuid not null references public.users(id),created_at timestamptz not null default now());
create table if not exists public.trip_members(trip_id uuid not null references public.trips(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,role text not null default 'traveler' check(role in('admin','planner','traveler')),status text not null default 'pending' check(status in('pending','in','out','auto_out')),payment_status text not null default 'none' check(payment_status in('none','sent','confirmed')),joined_at timestamptz not null default now(),responded_at timestamptz,primary key(trip_id,user_id));
create table if not exists public.events(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id) on delete cascade,user_id uuid references public.users(id) on delete set null,event_type text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists events_trip_created_idx on public.events(trip_id,created_at desc);
create table if not exists public.pokes(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id) on delete cascade,from_user uuid not null references public.users(id),to_user uuid not null references public.users(id),channel text not null check(channel in('sms','concierge')),created_at timestamptz not null default now(),completed_at timestamptz);
-- The MVP uses server-side service-role access. Never expose the service key to the browser.
